// Extraction des métadonnées de la réunion depuis le webhook
const body = $input.first().json.body || $input.first().json;
const audioUrl  = body.audio_url || body.file_url || '';
const reunionDate = body.date || new Date().toLocaleDateString('fr-FR');
const participants = body.participants || 'Non précisé';
const sujet = body.sujet || body.title || 'Réunion';
const langue = body.langue || 'fr';

return [{ json: {
  audio_url: audioUrl,
  reunion_date: reunionDate,
  participants: participants,
  sujet: sujet,
  langue: langue,
  timestamp: new Date().toISOString()
}}];

