const gpt = $input.first().json;
const content = gpt.choices[0].message.content;
let cr;
try { cr = JSON.parse(content); } catch(e) { cr = { resume_executif: content }; }

const meta = $('Extraire infos réunion').first().json;
const date = meta.reunion_date;
const sujet = meta.sujet;
const participants = meta.participants;

// Construire le HTML du compte rendu
const actionsHtml = (cr.actions || []).map(a =>
  `<tr><td>${a.responsable||''}</td><td>${a.action||''}</td><td>${a.echeance||''}</td></tr>`
).join('');

const html = `
<h1>Compte Rendu de Réunion</h1>
<p><strong>Date :</strong> ${date} | <strong>Sujet :</strong> ${sujet}</p>
<p><strong>Participants :</strong> ${participants}</p>
<hr/>
<h2>Résumé exécutif</h2>
<p>${cr.resume_executif||''}</p>
<h2>Points discutés</h2>
<ul>${(cr.points_discutes||[]).map(p=>`<li>${p}</li>`).join('')}</ul>
<h2>Décisions prises</h2>
<ul>${(cr.decisions_prises||[]).map(d=>`<li>${d}</li>`).join('')}</ul>
<h2>Plan d'action</h2>
<table border="1" cellpadding="8" style="border-collapse:collapse;width:100%">
<tr><th>Responsable</th><th>Action</th><th>Échéance</th></tr>
${actionsHtml}
</table>
<h2>Prochaine réunion</h2>
<p>${cr.prochaine_reunion||'À définir'}</p>
<hr/><p style="font-size:11px;color:#888">Généré automatiquement par TransferAI — ${new Date().toLocaleString('fr-FR')}</p>
`;

return [{ json: {
  compte_rendu_json: cr,
  compte_rendu_html: html,
  sujet: sujet,
  date: date,
  participants: participants,
  nb_actions: (cr.actions||[]).length
}}];
